  function ideasPanel(){const m=metric(),list=m.recommendations?.length?m.recommendations:ui.recommendations;return `<div class="section-title">把有限空间，用在喜欢的事上</div><p class="helper">根据房间、已有家具、通道偏好和预算，找更合适的尺寸与布局。</p><button type="button" class="button dark full" data-action="recommend">✧ 生成实用规格建议</button><div class="recommend-list">${list.length?list.map((r,i)=>`<article class="recommend-card"><h3>${esc(r.title||r.name||'空间建议 '+(i+1))}</h3><p>${esc(r.reason||r.description||'结合你的现有布局，选择更合适的家具规格。')}</p>${r.dimensions?`<p>${esc(r.dimensions)}</p>`:''}<button type="button" data-action="apply-recommendation" data-id="${esc(r.id)}">应用此建议 ↗</button></article>`).join(''):'<div class="empty-state">小房间，也有大办法。<br>先完成房屋尺寸，再生成你的第一组建议。</div>'}</div><div class="divider"></div><div class="section-title">优先满足什么？</div><div class="field-grid">${input('家具预算上限','profile.budget',finite(project().profile?.budget,20000),{unit:'¥',min:0,max:10000000,step:100})}${input('希望保留通道','profile.minPassage',cm(project().profile?.minPassage||650),{min:30,max:200})}</div><label class="checkbox-row"><input type="checkbox" data-bind="profile.rental" ${project().profile?.rental?'checked':''}> 租房优先 · 可拆装、少改造</label><div class="quality-note">建议为通用规格与布置思路，不含付费排名。购买前请核对真实商品、门洞及电梯搬运尺寸。</div>`}
