    return `<div class="inspector-eyebrow">${mounted?'MAKE THE WALL WORK':'THE DETAILS MAKE A HOME'}</div><div class="object-preview">${furnitureArt(cat?.category||'storage',item.type)}</div><div class="selection-title"><div><input class="object-name-input" type="text" data-bind="item.${esc(item.id)}.name" value="${esc(item.name||cat?.label||cat?.name||'家具')}" maxlength="60" aria-label="家具名称"><div class="inspector-subtitle">${esc(categories[cat?.category]||'家具')} · ${mounted?'不占地面，向墙面要空间':'自定义规格'}</div></div><i class="selected-dot"></i></div><div class="section-title">外形尺寸<span class="sub">宽 × 深 × 高</span></div><div class="field-grid selection-dimensions three">${input('宽度',`item.${item.id}.w`,cm(item.w),{min:1,max:600})}${input('深度',`item.${item.id}.d`,cm(item.d),{min:1,max:600})}${input('高度',`item.${item.id}.h`,cm(item.h),{min:1,max:600})}</div><div class="divider"></div><div class="section-title">${mounted?'挂墙安装位置':'摆放位置'}</div><div class="field-grid">${position}${input('参考单价',`item.${item.id}.price`,item.price==null?'':finite(item.price),{unit:'¥',min:0,max:10000000,step:1,full:mounted})}</div>${mounted?installNote(item,cat):'<p class="mini-note">坐标为房间模型坐标。转角桌与格架按外包络估算占地和通道；收纳按模板比例估算，非实测。</p>'}<div class="divider"></div><div class="section-title">家具饰面<span class="sub">按用途筛选</span></div>${opts.length?select('材质与板材饰面',`item.${item.id}.material`,item.material,opts,true):'<p class="helper">这件物品暂时保留原有材质，可自由调整颜色。</p>'}${finishList.length?`<div class="finish-grid item-finishes">${finishList.map(f=>`<button type="button" class="finish-card ${item.material===f.id?'active':''}" data-action="item-finish" data-id="${esc(item.id)}" data-finish="${esc(f.id)}"><i style="background:${esc(f.color||'#c4b28d')}">${f.preview||f.textureRef?materialThumb(f.id,f.label,'finish',item.type):''}</i><strong>${esc(f.label||f.id)}</strong><small>${esc(finishGroups[f.group]||f.group||'家具饰面')}</small></button>`).join('')}</div>`:''}${selectedMat&&(selectedMat.preview||selectedMat.textureRef)?`<p class="mini-note">当前：${esc(selectedMat.label||selectedMat.id)} · 颜色可在下方独立调整。</p>`:''}<div class="divider"></div><div class="section-title">表面颜色<span class="sub">${homeColors.length} 色 + 自定义</span></div>${colorPalette(`item.${item.id}.color`,item.color||'#c1aa85')}${customColor(`item.${item.id}.color`,item.color||'#c1aa85','自定义家具色')}<p class="mini-note">纯色板与烤漆按所选基色呈现；纯白为白色漆面，可继续搭配其他配色。</p><div class="property-actions"><button type="button" data-action="duplicate-item" data-id="${esc(item.id)}">⧉ 复制${mounted?'挂件':'家具'}</button><button type="button" class="delete" data-action="delete-item" data-id="${esc(item.id)}">删除${mounted?'挂件':'家具'}</button></div><button type="button" class="button outline full" data-action="deselect">完成选择</button><div class="divider"></div><p class="mini-note">尺寸与饰面为可编辑方案模型，价格为示意预算；购买前请核对实物尺寸与安装条件。</p>`;
