  function renderInspector(force=false){
    const s=data(),host=$('#inspectorContent');if(!s)return;const item=project().items?.find(i=>i.id===s.selectedId),checking=ui.mobilePanel==='check'&&matchMedia('(max-width:900px), (orientation:landscape) and (max-width:1100px) and (max-height:600px)').matches;
    const signature=JSON.stringify([s.selectedId,checking,item||null,checking||!item?s.metrics:null]);if(!force&&signature===ui.inspectorSignature)return;
    if(!force&&(focusedEditor(host)||ui.commitHost===host||ui.pressHost===host)){host.dataset.pendingRender='true';return}
    const saved=captureEditor(host),scroller=$('#inspectorPanel'),scrollTop=scroller.scrollTop;
    host.innerHTML=checking?checkContent():item?itemInspector(item):checkContent();ui.inspectorSignature=signature;delete host.dataset.pendingRender;
    restoreEditor(host,saved);scroller.scrollTop=scrollTop;hydrateMaterialPreviews();
  }
  function render(state){if(!state)return;ui.state=state;$('#saveStatus').innerHTML='<i></i>'+esc(state.saving||'本机自动保存');const p=state.project||{},s=p.structure||{},m=state.metrics||{},h=state.history||{};if(document.activeElement!==$('#projectName'))$('#projectName').value=p.name||'我的日光小屋';$$('[data-action=undo]').forEach(b=>b.disabled=!h.canUndo);$$('[data-action=redo]').forEach(b=>b.disabled=!h.canRedo);const area=finite(m.area);$('#roomSummary').textContent=area?`${num(area)} m² · ${s.shape==='custom'?'自定义户型':s.shape==='L'||s.shape==='l'?'L 形房间':'我的一间房'}`:'一间房，无限种可能';const renderer=state.renderer;$('#rendererStatus').innerHTML=`<i></i>${esc(typeof renderer==='string'?renderer:renderer?.label||renderer?.name||renderer?.type||'实时空间')}`;$('#metricArea').innerHTML=`${num(m.area)}<small>m²</small>`;$('#metricFree').innerHTML=`${num(m.freeArea)}<small>m²</small>`;$('#metricPassage').innerHTML=`${m.minPassage==null?'—':num(m.minPassage/10,0)}<small>cm</small>`;$('#metricStorage').innerHTML=`${num(m.storage,0)}<small>L</small>`;$('#metricBudget').textContent=`¥ ${m.knownCost==null?'—':money(m.knownCost)}`;const hour=finite(p.environment?.hour,14);$('#hourRange').value=hour;$('#hourOutput').textContent=`${String(Math.floor(hour)).padStart(2,'0')}:${String(Math.round((hour%1)*60)).padStart(2,'0')}`;$$('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===state.view));$('#canvasHint').textContent=state.tool==='walls'?'拖动墙角 · 点数字修改尺寸':state.view==='plan'?'点击选择 · 拖动家具 · 双指缩放':state.view==='eye'?'拖动转向 · 滚轮前后':'拖动环绕 · 双指缩放';const dims=state.dimensions??state.showDimensions??true,open=state.openings??state.showOpenings??false;$('#dimensionButton').classList.toggle('active',Boolean(dims));$('#dimensionButton').setAttribute('aria-pressed',String(Boolean(dims)));$('#openingButton').classList.toggle('active',Boolean(open));$('#openingButton').setAttribute('aria-pressed',String(Boolean(open)));const count=(m.collisions?.length||0)+(m.warnings?.length||0);$('#mobileWarningCount').textContent=count?`· ${count}`:'';if(state.selectedId&&state.selectedId!==ui.lastSelected&&matchMedia('(max-width:900px), (orientation:landscape) and (max-width:1100px) and (max-height:600px)').matches){ui.mobilePanel='details';ui.open=true;syncMobile()}ui.lastSelected=state.selectedId;renderLibrary();renderInspector();}
  function syncMobile(){app.dataset.mobilePanel=ui.mobilePanel;app.dataset.panelOpen=String(ui.open);$$('.mobile-panel-switch [data-mobile-panel]').forEach(b=>b.classList.toggle('active',b.dataset.mobilePanel===ui.mobilePanel));requestAnimationFrame(()=>window.dispatchEvent(new Event('resize')))}
  function setTab(tab){ui.tab=tab;ui.mobilePanel='library';ui.open=true;syncMobile();renderLibrary(true);$('#libraryContent').scrollTop=0}
  function dialog(title,content){$('#dialogTitle').textContent=title;$('#dialogContent').innerHTML=content;closePopover();const d=$('#sunroomDialog');if(!d.open)d.showModal();setTimeout(()=>$('#dialogContent input')?.focus({preventScroll:true}),40)}
  function closeDialog(){$('#sunroomDialog').close()}
